import json,re,html,hashlib
from pathlib import Path
W=Path(__file__).parent
B=Path('/tmp/tzidkat-current-batch2/mcp-data/text')
D=json.loads((W/'primary-86-90.json').read_text())
R=json.loads((W/'extra-primary-86-90.json').read_text()); R.update(json.loads((W/'extra-primary-86-90b.json').read_text()))
def plain(t):
    if isinstance(t,list):t=' '.join(plain(x) for x in t)
    return ' '.join(html.unescape(re.sub('<[^>]*>','',t)).replace('\u200e','').replace('\u200f','').split())
def bare(t):return re.sub('[\u0591-\u05bd\u05bf-\u05c2\u05c4-\u05c5\u05c7]','',plain(t))
def src(ref,*inds):
    t=D[ref]['data']['he']
    for i in inds:t=t[i-1]
    return bare(t)
def local(book,ref,lo=0,hi=None):
    r=next(r for r in json.loads((B/f'{book}.json').read_text())['paras'] if r['r']==ref)
    return plain([x[0] for x in r['p'][lo:hi]]) if 'p' in r else plain(r['t'])
def cut(t,a,b=None):
    i=t.index(a)
    return t[i:] if b is None else t[i:t.index(b,i)+len(b)]
P={86:([237,238,239],[273,274,275,276]),87:([239,240,241],[276,277,278]),88:([241,242],[278,279]),89:([242,243,244,245,246],[279,280,281,282,283]),90:([246,247,248,249],[283,284,285])}
E=[]
def add(s,id,pi,ref,he,en,ctx,book=None,url=None,anchorEnd=None):
    rows=json.loads((W.parent/'live-baseline'/f'{s-1}.json').read_text());r=next(r for r in rows if r.get('n')==1)
    prefix=plain(r['p'][pi][0]);prefix=prefix if anchorEnd is None else prefix[:prefix.index(anchorEnd)+len(anchorEnd)]
    url=url or ('#/read/'+ref.replace(' ','_') if book else 'https://www.sefaria.org/'+ref.replace(' ','_'))
    ev={'ref':ref,'url':url,'he':plain(he),'en':en,'heSha256':hashlib.sha256(plain(he).encode()).hexdigest(),'translation':'Original English translation prepared directly from the original Hebrew or Aramaic source.','coverage':'Complete selected source unit with all qualifications necessary to its meaning.'}
    if book:ev.update(canonicalReaderRef=ref,canonicalSourceFile=f'mcp-data/text/{book}.json')
    e={'section':s,'id':id,'rowN':1,'phraseIndex':pi,'heAnchorPrefix':prefix,'heCharOffset':len(prefix),'ref':ref,'url':url,'he':plain(he),'en':en,'context':ctx,'sourceEvidence':[ev],'reviewEvidence':{'pdfPages':{'neimosA':P[s][0],'integratedA':P[s][1]},'preserveExisting':True,'status':'verified','dedup':'All destination native and connected quotations compared; no existing complete source passage is replaced or duplicated.','method':'Both supplied editions reviewed; original sources read in context; exact canonical Hebrew prefix checked.'}}
    if book:e['readerRef']=ref
    else:e['openExternal']=True
    E.append(e)

def extra(ref,*inds):
    t=R[ref]['versions'][0]['text']
    for i in inds:t=t[i-1]
    return bare(t)

add(86,'maharal-possessions-and-life',0,'Netivot Olam, Netiv Gemilut Chasadim 5',
    'והנה האדם יש בו ד\' חלקים אלו, הא\' הוא הגוף, הב\' הוא הנפש, הג\' הוא השכל, הד\' הוא ממון של אדם, אף כי אין הממון הוא האדם עצמו, הרי בארנו כי גם הממון נכנס בגדר האדם לפי שהממון הוא חיותו ויש שממונו חביב עליו יותר מגופו ודבר זה בארנו כמה פעמים.',
    'A person has these four parts: the first is the body, the second the soul, the third the intellect, and the fourth a person’s property. Although property is not the person himself, we have explained that property too enters into the definition of the person, because property is his livelihood; there are people whose property is dearer to them than their body. We have explained this several times.',
    'Maharal includes possessions because they sustain a person’s life, while expressly distinguishing them from the person himself. This supplies the conceptual connection between property and personal vitality.',url='https://he.wikisource.org/wiki/נתיבות_עולם/נתיב_גמילות_חסדים/ה')
E[-1]['sourceEvidence'][0].update(webRef='turn66view0',sourceLocation='Paragraph beginning וכנגד אלו; complete four-part definition from והנה האדם through כמה פעמים.')
add(86,'rabbeinu-bahya-four-orders-of-creatures',1,'Rabbeinu Bahya, Shemot 35:1:2',cut(src('Rabbeinu Bahya, Shemot 35:1',2),'וידוע כי','בנפש השכלית.'),
    'It is known that the lower creatures have four divisions, one above another: the inanimate, the growing, the living, and the speaking. The inanimate are mountains and hills; this division has no soul at all, neither a vegetative soul nor a soul of movement, and certainly no intellectual soul. Above it is the growing: it has an advantage over the inanimate because it has a vegetative soul. Above the growing are the other living creatures, which have a soul of movement and a vegetative soul. Above the living creatures that do not speak is the human being, who includes them all through his vegetative soul and his soul of movement, and has an advantage over them all through his intellectual soul.',
    'Rabbeinu Bahya defines the four traditional categories and explains how the human being includes the powers of the preceding levels. The next sentence traces their order in the creation account.')
add(86,'shaarei-kedusha-humanity-includes-worlds',1,"Sha'arei Kedusha, Part 3 2:30",src('Shaarei Kedusha, Part 3 2',30),
    'The nature of the human being has now been thoroughly explained: he includes all the worlds, both in their general structure and in their particulars. This is unlike all the other upper and lower creatures, for whatever is produced in any one world includes only the world in which it was created.',
    'Rabbi Chaim Vital gives the wider account of the human being as including the worlds. This addresses the ois’s statement that the other creatures are rooted in the human soul.')
ref='Machshavot Charutz 11:1'
add(86,'machshavot-letters-and-the-human-microcosm',1,ref,local('machshavot-charutz',ref,9,13),
    'Every creature has particular letters through which it was created, and they are the root of its vitality and continued existence. The human being, who is called a “small world” because he includes the whole creation and the entire world, has all twenty-two letters. Therefore it is said of him, “In Our image, according to Our likeness.” The whole Book of Formation explains this: how everything—the world and the human being—was created through the twenty-two letters.',
    'Rav Tzadok explains the shared root through the letters of creation: an individual creature embodies particular letters, while the human being includes the full alphabet.',book='machshavot-charutz')
ref='Tzidkat HaTzadik 91:1'
add(86,'tzidkat-relations-to-possessions-and-their-repair',2,ref,local('tzidkat-hatzadik',ref,15,24),
    'According to the distance that his light and vitality extend into them, so are their character and their relation to him. Some are his possessions; some were in his hands for a time and he sold them; some were only borrowed or rented for a short time; some he saw with other people or looked at while passing through a place; some he never saw in his life but desired in his thoughts. There are countless such degrees. One who understands the matter can know and reflect upon how to repair all these. Their repair comes only by returning them to the source: to know that everything comes from the very vitality of the blessed God, who gives it life and sustains it; without this, it would be as though it did not exist.',
    'The later ois distinguishes degrees of connection to objects and gives their common repair. It makes the present account of ownership part of a broader relationship to the source of life.',book='tzidkat-hatzadik')
ref='Tzidkat HaTzadik 197:1'
add(86,'tzidkat-divine-love-in-possessions',6,ref,local('tzidkat-hatzadik',ref,13,27),
    '“With all your resources,” however, is not within the power of human service alone, but comes through assistance from Heaven. Its meaning is that love of the blessed God should be established in all one’s property and possessions. It does not refer to one’s desire and longing for property, which is already included in “with all your heart,” but to the property itself. As is known, property belongs to the person; the person becomes so completely filled with love of the blessed God in all his depths that his possessions, which are his extension, are themselves filled with His love. This is like Rabbi Pinchas ben Yair’s donkey, which was stringent with itself about eating forbidden food. This concerns living creatures, and presumably the same applies to inanimate things, as in “A stone will cry out from the wall” in the future, when someone wishes to commit a transgression, as our Sages taught. This is the meaning of one’s utensils resting on Shabbat: then one is wholly for Hashem, including all one’s possessions. Similarly, our father Yaakov’s flocks numbered six hundred thousand, according to our Sages; the correspondence in number shows that they embodied the six hundred thousand souls of Israel. Certainly love of the blessed God was established in them too. The Zohar says that Yaakov’s intention with the rods concerned tefillin: the binding and attachment of his whole soul to the blessed God. Yaakov’s quality corresponds to “with all your resources”: binding his whole being and soul so completely that the possessions belonging to him are also included in this bond. Therefore this is not stated in “If you will indeed listen,” which addresses the many, for this level belongs only to individuals who merit it. The many cannot attain this level until the future, when He pours out His spirit upon all flesh.',
    'This parallel describes holiness extending into possessions and preserves Rav Tzadok’s express limitation: in the present, this degree belongs to individuals who merit it; its general realization belongs to the future.',book='tzidkat-hatzadik')
add(86,'rambam-knowledge-and-the-end-of-hostility',4,'Guide for the Perplexed III:11, Ibn Tibbon translation',
    'ואילו היה שם חכמה אשר יחסה לצורה האנושית כיחס הכח הרואה אל העין, היו נפסקין נזקיו כולם לעצמו ולזולתו, כי בידיעת האמת תסור השנאה והקטטה ויבטל היזק בני אדם קצתם לקצתם. כבר יעד אותו ואמר וגר זאב עם כבש וגו\' (ישעיהו יא ו) ופרה ודב וגו\' (ישעיהו יא ז) ושעשע יונק וגו\' (ישעיהו יא ח); ואחר כן נתן סבתו ואמר כי הסבה בהסתלק השנאות והקטטות וההתגברויות, הוא ידיעת בני אדם בעת ההיא באמתת השם, אמר לא ירעו ולא ישחיתו בכל הר קדשי כי מלאה הארץ דעה את ה׳ כמים לים מכסים (ישעיהו יא ט). ודעהו:',
    'If there were wisdom whose relation to the human form was like that of the power of sight to the eye, all a person’s injuries to himself and to others would cease. Through knowledge of the truth, hatred and strife depart, and the harm people do to one another is abolished. This has already been promised: “The wolf shall dwell with the lamb,” “The cow and the bear,” and “The nursing child shall play.” It then gives the cause: the removal of hatred, quarrels, and domination will result from people’s knowledge at that time of the truth of God. It says: “They shall neither harm nor destroy throughout My holy mountain, for the earth shall be filled with knowledge of Hashem as the waters cover the sea.” Know this.',
    'Rambam explains these verses through the removal of human hostility by knowledge of God. This is a parallel interpretation of the same prophecy; Rav Tzadok’s present discussion develops the relationship between the human being and the other creatures.',url='https://he.wikisource.org/wiki/מורה_נבוכים_(אבן_תיבון)/חלק_ג/פרק_יא')
E[-1]['sourceEvidence'][0].update(webRef='turn66view1',sourceLocation='Second and final paragraph, ואילו היה שם חכמה through ודעהו. Medieval Ibn Tibbon Hebrew; modern Hebrew and English translations are not used.')
add(86,'sanhedrin-uncorrupted-animals-in-the-ark',8,'Sanhedrin 108b:6-7',src('Sanhedrin 108b',6)+' '+src('Sanhedrin 108b',7),
    '“From every clean animal take seven pairs for yourself, a man and his wife.” Do animals have marriage? Rabbi Shmuel bar Nachmani said in Rabbi Yonatan’s name: From those with which no transgression had been committed. How did he know? Rav Chisda said: He passed them before the ark. Whatever the ark admitted was known to have had no transgression committed with it; whatever the ark did not admit was known to have had a transgression committed with it. Rabbi Abbahu said: From those that came by themselves.',
    'The Gemara is the source for the qualification concerning the animals that entered the ark. Both explanations of how Noach identified them are retained.')

add(87,'avodat-yisrael-noachs-resistance-to-judgment',2,'Avodat Yisrael, Sefer Bereshit, Noach 6',extra('Avodat Yisrael, Sefer Bereshit, Noach',6),
    '“Noach entered because of the waters of the Flood.” Rashi explains: Noach too was of little faith; he believed and did not believe that the Flood would come, and did not enter until the water forced him. This is puzzling: could the righteous Noach, Heaven forbid, have lacked faith in his blessed Creator? We also know that he labored on the ark for one hundred and twenty years before the Flood and rebuked and warned his generation. Could he himself have been of little faith? The Sages’ words can be explained: it is the way of the righteous to sweeten judgments and seek the blessed God’s merciful favor toward His creatures. Even when it appears that the Holy One, blessed be He, decrees a decree, the righteous person increases prayer and holy thoughts until he draws mercy into the world. The Idra Rabba states: “The secret of Hashem is for those who fear Him; until they assent, judgments do not descend into the world.” Thus Noach the righteous, wishing to strengthen kindness and annul the decree of the Flood, did not allow the thought to spread in his heart that the King’s word had gone forth and could not be changed. He strengthened his thought instead: Hashem will return and relent, and His mercy will prevail over His attributes. Therefore the Sages called him, in their expressive language, “of little faith,” believing and not believing: he did not wish to believe, so as not to assent to the judgments. Only because he was alone in the world could he not save all his generation. He nevertheless did his part, and did not enter until the water forced him.',
    'Avodat Yisrael records the same additional clause in an interpretation of Noach’s hope for mercy. This establishes an earlier parallel for the wording while preserving the limitation that Noach’s effort did not save his generation. The existing note on the available Idra text remains in place.')
add(87,'nathans-parable-and-davids-verdict',4,'II Samuel 12:1-7',src('II Samuel 12:1-7'),
    'Hashem sent Natan to David. He came to him and said: “There were two men in one city, one rich and one poor. The rich man had very many sheep and cattle. The poor man had nothing but one small ewe that he had bought and raised. It grew up with him and his children, ate from his bread, drank from his cup, and lay in his bosom; it was like a daughter to him. A traveler came to the rich man. He spared his own sheep and cattle when preparing food for the guest who had come to him, and took the poor man’s ewe and prepared it for the man who had come.” David was very angry with the man and said to Natan: “As Hashem lives, the man who did this deserves death. He must repay the ewe fourfold, because he did this and had no compassion.” Natan said to David: “You are the man! Thus said Hashem, the God of Israel: I anointed you king over Israel, and I rescued you from Shaul’s hand.”',
    'Natan first presents another person’s apparent case; David pronounces judgment before recognizing its application to himself. This is the biblical example explicitly named in the Hebrew.')
add(87,'jeremiah-anathoths-threat-and-judgment',5,'Jeremiah 11:21-23',src('Jeremiah 11:21-23'),
    'Therefore thus said Hashem concerning the men of Anatot who seek your life, saying, “Do not prophesy in Hashem’s name, or you will die by our hand”: Therefore thus said Hashem of hosts: “I am about to call them to account. The young men shall die by the sword; their sons and daughters shall die by famine. No remnant shall remain of them, for I shall bring calamity upon the men of Anatot in the year of their reckoning.”',
    'These verses identify the men of Anatot and their threat against Yirmiyahu. They supply the background to the first example in the bracketed sentence.',anchorEnd='בִּבְנֵי עֲנָתוֹת')
add(87,'jeremiahs-prior-intercession-and-later-prayer',5,'Jeremiah 18:18-23',src('Jeremiah 18:18-23'),
    'They said: “Come, let us devise plans against Yirmiyahu, for instruction will not be lost from the priest, counsel from the wise, or a word from the prophet. Come, let us strike him with the tongue, and let us pay no attention to any of his words.” “Attend to me, Hashem, and hear the voice of my opponents. Should evil be repaid for good? For they have dug a pit for my life. Remember how I stood before You to speak good on their behalf, to turn Your wrath away from them. Therefore give their children over to famine and deliver them into the power of the sword; let their wives be bereaved and widowed, their men slain by death, and their young men struck by the sword in war. Let an outcry be heard from their houses when You suddenly bring a troop against them, for they have dug a pit to catch me and hidden snares for my feet. You, Hashem, know all their counsel against me for death. Do not atone for their iniquity, and do not erase their sin from before You. Let them stumble before You; deal with them at the time of Your anger.”',
    'The passage preserves both sides of Yirmiyahu’s prayer: his earlier intercession for their good and his later appeal after their plotting. It makes the tension raised by the ois explicit.',anchorEnd='בִּבְנֵי עֲנָתוֹת')
add(87,'sanhedrin-shevna-and-chizkiyahu',5,'Sanhedrin 26a:21-23',' '.join(src('Sanhedrin 26a',i) for i in range(21,24)),
    'What is a conspiracy of the wicked? Shevna taught thirteen myriads, while Chizkiyahu taught eleven myriads. When Sancheriv came and besieged Jerusalem, Shevna wrote a note and shot it out on an arrow: “Shevna and his company have made peace; Chizkiyahu and his company have not made peace.” This is as it is said: “For behold, the wicked bend the bow; they have readied their arrow on the string.” Chizkiyahu was afraid. He said: Perhaps, Heaven forbid, the Holy One’s judgment will incline after the majority; since the majority will be delivered into their hands, they too will be delivered. A prophet came and said to him: “Do not call a conspiracy everything that this people calls a conspiracy.” That is, it is a conspiracy of the wicked, and a conspiracy of the wicked does not enter the count.',
    'This is the original account of Shevna, the siege of Jerusalem, and the prophet’s response to Chizkiyahu. Its stated setting is Jerusalem; the connection to the ten tribes in the ois is Rav Tzadok’s application.',anchorEnd='בְּשֶׁבְנָא')
add(87,'avraham-and-lots-separation',5,'Genesis 13:8-9',src('Genesis 13:8-9'),
    'Avram said to Lot: “Please let there be no strife between me and you, or between my herdsmen and yours, for we are kinsmen. Is not the whole land before you? Please separate from me. If you go left, I will go right; if you go right, I will go left.”',
    'This is the earlier separation of Lot mentioned in the ois. The request is framed as a way to end strife between relatives.',anchorEnd='הִפְרִיד לוֹט מִקּוֹדֶם')
add(87,'shabbat-righteous-bear-the-generation',7,'Shabbat 33b:4',cut(src('Shabbat 33b',4),'דאמר רבי גוריון','הממושכנין על הרועים.'),
    'Rabbi Guryon said—and some say Rav Yosef bar Shemaya: When there are righteous people in the generation, the righteous are seized on account of the generation. When there are no righteous people in the generation, the children of the study house are seized on account of the generation. Rabbi Yitzchak bar Ze’iri said—and some say Rabbi Shimon ben Nezira: What is the verse? “If you do not know, fairest among women, go forth in the footsteps of the flock.” We interpret this as the kids taken as pledges for the shepherds.',
    'The Gemara supplies the expression that the righteous bear the generation’s suffering. Both clauses of the teaching are included, together with its scriptural image.')
add(87,'bava-kamma-calamity-begins-with-righteous',9,'Bava Kamma 60a:16-17',src('Bava Kamma 60a',16)+' '+src('Bava Kamma 60a',17),
    'Rabbi Shmuel bar Nachmani said in Rabbi Yonatan’s name: Calamity comes to the world only when the wicked are in the world, and it begins with the righteous first, as it is said: “When fire goes forth and finds thorns.” When does fire go forth? When thorns are available to it. It begins with the righteous first, as it is said, “And a stack has been consumed”: it does not say, “It consumes a stack,” but “A stack has been consumed”—the stack has already been consumed. Rav Yosef taught: What is meant by “None of you shall go out from the door of his house until morning”? Once permission has been given to the destroyer, it does not distinguish between the righteous and the wicked. Moreover, it begins with the righteous first, as it is said: “I shall cut off from you the righteous and the wicked.”',
    'This is the separate Talmudic passage explicitly describing calamity as beginning with the righteous. The existing note concerning a person who invokes heavenly judgment against another is preserved with its own qualification.')
add(87,'mashiachs-defense-leading-to-repentance',11,'Mekor Mayim Chayim on Baal Shem Tov, Bereshit 100:1',cut(extra('Mekor Mayim Chayim on Baal Shem Tov, Bereshit 100:1'),'ובריש','כו\' ע"ש,'),
    'At the beginning of the new Midrash Pinchas it is written in the name of the righteous Rabbi Gedaliah of Linitz, who said in the name of his teacher, the righteous rebuker: Mashiach will offer a favorable defense of all Israel, even of the wicked, showing that they are in the right. Through the favorable defense he offers for them, they will return in repentance, and through this they will be redeemed, for they are redeemed through repentance. He would say: A small righteous person loves small sinners; a great righteous person loves great sinners; but Mashiach will love and offer a favorable defense even of utterly wicked people. Anyone who offers a favorable defense of all creatures has an aspect of Mashiach.',
    'The recorded teaching connects Mashiach’s comprehensive defense of people with their return in repentance. The concluding condition—repentance leading to redemption—is part of the quotation. The attribution follows the transmission stated in the source.')

add(88,'rashi-no-road-without-bends',0,'Rashi on Deuteronomy 1:22:3',src('Rashi on Deuteronomy 1:22',3),
    '“The road by which we shall ascend”—There is no road that has no bends.',
    'Rashi’s literal explanation supplies the wording that Rav Tzadok applies here to a person’s moral path.',anchorEnd='אֵין דֶּרֶךְ שֶׁאֵין בּוֹ עֲקַלְקַלּוֹת')
add(88,'noam-elimelech-repairing-a-path',0,'Noam Elimelech, Devarim, ותקרבון אלי',
    'אלא נ"ל דכוונת ישראל היה בשליחות המרגלים כדי שהם יתקנו בעלותם כל דבר רע ולהכניע השרים בצדקתם, וכדי שיבואו ויאמרו טובה הארץ ויפעול דיבורם שאחר זה לא יהיה שום מונע בבואם אל הארץ ויבואו בהשקט ובטח, וזהו שהוכיח אותם משה רבינו ע"ה "ותקרבון כו\' ונשלחה אנשים" צדיקים כפירש"י ז"ל שאותה שעה כשרים היו, "ויחפרו לנו את הארץ", דהיינו שהם בצדקתם יעשו חפירה בהילוכם לתקן כל המכשולות והעקמומית והקטרוגים, וזהו לשון חפירה דהיינו שצריך להיות בהסתר כנ"ל, וזהו "את הדרך אשר נעלה בה" כפירוש רש"י ז"ל שאין דרך שאין בו עקמומיות, רמז לכל המכשולות והקטרוגים והמסכים כנ"ל, "ואת הערים אשר נבא כו\'" ר"ל שאז נבא בקל אל הערים, זהו שנאמר "וייטב בעיני הדבר", כי לפי כוונתם היה הדבר טוב, וזהו "ויפנו כו\'" שהיו מרגלים פונים אל הדבר הזה ונתנו לבם על זאת, "וישיבו אותנו דבר ויאמרו טובה הארץ", ולפי ענינינו הוא מובן מה שלא הזכיר להם הוצאת דבת הארץ, שזה היה קלקולם שלא האמינו מיד מה שאמרו המרגלים טובה הארץ, כי כוונתם לזה כנ"ל שיבואו ויאמרו טובה הארץ ולא היה [להם] לפנות אל שאר הדברים.',
    'It appears to me that Israel’s intention in sending the scouts was that, as they went up, they would repair every harmful thing and subdue the heavenly princes through their righteousness. They would return and say, “The land is good,” and their speech would act so that no obstacle remained when Israel entered the land, allowing them to enter quietly and securely. This is Moshe’s rebuke: “You approached … let us send men”—righteous men, as Rashi explains that at that time they were worthy. “Let them explore the land for us”: through their righteousness they would dig as they went, repairing all the obstacles, bends, and accusations. The language of digging signifies that this must be done in concealment. “The road by which we shall ascend,” as Rashi explains, “There is no road without bends,” alludes to all these obstacles, accusations, and barriers. “And the cities to which we shall come” means that we could then enter the cities easily. Therefore it says, “The matter was good in my eyes,” for according to their intention the matter was good. “They turned” means that the scouts directed themselves toward this and set their hearts upon it. “They brought us back word and said, ‘The land is good.’” According to this explanation, we understand why he did not mention their evil report about the land: their failure was that they did not immediately trust the scouts’ statement, “The land is good.” Their intended purpose was that the scouts should come and say, “The land is good,” and they should not have turned to the other matters.',
    'Noam Elimelech develops Rashi’s road imagery into the removal of spiritual obstacles. The quotation retains the contrast between the original worthy intention and the later failure to trust.',url='https://he.wikisource.org/wiki/נועם_אלימלך/פרשת_דברים',anchorEnd='אֵין דֶּרֶךְ שֶׁאֵין בּוֹ עֲקַלְקַלּוֹת')
E[-1]['sourceEvidence'][0].update(webRef='turn68view3',sourceLocation='Complete paragraph אלא נ"ל דכוונת ישראל, following עוד בפסוק הנ"ל.')
add(88,'metzudot-self-judgment-and-gods-knowledge',0,'Metzudat David on Proverbs 21:2',src('Metzudat David on Proverbs 21:2'),
    '“Right in his eyes”—because he does not see fault in himself. “And He weighs”—Hashem is within his heart and knows whether his way is straight or not.',
    'Metzudat David explains both halves of the verse: the person’s self-favoring view and God’s knowledge of the heart.')
add(88,'rabbeinu-yonah-purifying-the-heart-with-help',6,'Rabbeinu Yonah on Berakhot 21a:8',extra('Rabbeinu Yonah on Berakhot 21a',8),
    '“So that they should direct their hearts to the Omnipresent.” Some explain that they put aside troubling thoughts and concentrate on reciting the prayer. This does not appear correct to my teacher, for then it should say “toward their prayer,” not “to the Omnipresent.” Below, when intention concerning the recitation is mentioned, it says that one who prays must direct his heart, giving as an indication, “You prepare their heart; You attend with Your ear.” Rather, the explanation is that they should intend that their heart be whole in the service of the Omnipresent and remove the pleasures and enjoyments of this world from their heart. When they purify their heart of this world’s vanities and direct their intention toward God’s greatness, their prayer will be desired and accepted. Of this intention it is said, “You prepare their heart; You attend with Your ear.” “You prepare their heart” is stated because the intention to purify the heart from transgressions and worldly pleasures requires assistance from the Omnipresent, as it is said, “Hashem prepares hearts,” and “Prepare their heart toward You.” Thus it asks: Help them and prepare their heart to be pure, so that You will attend to their prayer. Know that this is the principal explanation, since below it says, “An indication for the matter.” Why call it an indication when it would be a clear proof? Because the verse’s main subject is the intention to purify the heart, not the intention in reciting prayer; when it is cited concerning the recitation, it is called an indication.',
    'The commentary explicitly reads ותוכן לבות in relation to divine help in purifying the heart. It also distinguishes inward preparation for service from concentration on the words of prayer.')
add(88,'rabbeinu-bahya-preparation-and-assistance',7,'Rabbeinu Bahya, Devarim 29:18:3',src('Rabbeinu Bahya, Devarim 29:18',3),
    'If someone asks: How can Scripture punish a thought without an act? Surely a person cannot control himself so that bad thoughts never arise in his heart; why punish what is beyond his control? I will explain the principle. The choice of deeds, for good or evil, is entrusted to the person, as it is written, “See, I have set before you today life and good, death and evil … choose life.” The choice of thought is also entrusted to him after preparation: he is commanded to think a good thought and warned to turn his heart away from a bad thought, receiving reward for a good thought and punishment for a bad thought. When his reflections sometimes produce thoughts that are not good, and unworthy thoughts suddenly arise in his heart unintentionally, this is before preparation and is a sign of stumbling and sin: he has turned from the way and has not developed his soul through preparation. His repair and healing are to work at preparation—to direct his heart and thoughts toward the exalted God, subjecting and bending his thought to Him through good thought and worthy deeds. If a bad thought comes, he should rebuke it; if he does not rebuke it and it remains in his heart, he is punished. When he maintains this thought for a long time, preparing his heart to love the blessed God, draw near to Him, and walk in His ways, Hashem too will give good and reward his righteousness by preparing his heart so that he will not think of evil and only good will arise in his thought. Of this they said: “One who comes to purify himself is helped.” Many verses state this principle: “For Hashem searches all hearts and understands every formation of thoughts; if you seek Him, He will be found by you”; and “Hashem prepares hearts,” for the blessed God prepares a person’s heart and straightens his disposition when the person prepares his heart toward Him. Likewise, “You have heard the desire of the humble, Hashem; You prepare their heart; You attend with Your ear”; and “Hashem, God of Avraham, Yitzchak, and Israel our fathers, preserve this forever in the formation of Your people’s thoughts, and prepare their heart toward You.”',
    'Rabbeinu Bahya connects divine assistance with sustained preparation and the response to thoughts when they arise. The whole selected discussion is retained, including its question about involuntary thoughts and the distinction between their arrival and allowing them to remain. This is one explanation within his discussion; the following paragraph records additional interpretations.')
add(88,'avodah-zarah-no-arbitrary-demand',7,'Avodah Zarah 3a:12',src('Avodah Zarah 3a',12),
    'Rather, the Holy One, blessed be He, does not deal with His creatures arbitrarily. Why is it called a “light mitzvah”? Because it involves no monetary loss.',
    'The statement appears in the discussion of granting the nations an opportunity to perform the mitzvah of sukkah. Rav Tzadok uses its principle concerning divine fairness in his account of a sincere heart.')
add(88,'berakhot-straightening-the-heart',8,'Berakhot 59a:12',cut(src('Berakhot 59a',12),'אמר רבי אלכסנדרי','שיראו מלפניו״.'),
    'Rabbi Alexandri said in Rabbi Yehoshua ben Levi’s name: Thunder was created only to straighten the crookedness in the heart, as it is said: “God has acted so that they should fear Him.”',
    'The Talmud uses the same image of crookedness in the heart and identifies reverence for God as its correction.')

add(89,'yerushalmi-craft-of-priestly-divisions',3,'Jerusalem Talmud Sukkah 5:8:6',cut(src('Jerusalem Talmud Sukkah 5:8',6),'ויעשו אותן עשרים ושלש'),
    'Let them make them twenty-three divisions. This cannot be done, for it is written: “David and Shmuel the seer established them in their faithfulness”—read this as “in their craftsmanship.” Great craftsmanship was involved: no division received an ancestral field a second time before its fellow had received one. Rabbi Abbahu said: I calculated it; no division received an ancestral field a second time before its fellow had received one.',
    'The discussion asks why the twenty-four priestly divisions cannot be reduced to twenty-three. Its carefully balanced arrangement is called “great craftsmanship,” supplying Rav Tzadok’s example of the word craft applied to demanding wisdom.')
add(89,'devarim-rabbah-torah-loosens-the-tongue',9,'Devarim Rabbah 1:1',cut(src('Devarim Rabbah 1:1'),'ולשונה של תורה מתיר את הלשון'),
    'The language of Torah also loosens the tongue. Know this: in the future the Holy One, blessed be He, will bring forth excellent trees from the Garden of Eden. What is their excellence? They heal the tongue, as it is said: “Along the river, on its banks on either side, there shall grow…” How do we know that this is healing of the tongue? It says: “Its fruit shall be for food and its leaf for healing.” Rabbi Yochanan and Rabbi Yehoshua ben Levi offered two explanations: one said, “For loosening”; the other said that anyone who is mute and swallows some of it has his tongue healed and immediately polishes it with words of Torah. For it says “on this side and on that side,” and this expression refers to Torah, as it is said: “They were written on this side and on that side.” Rabbi Levi said: Why learn from elsewhere? Let us learn from the passage itself. Before Moshe merited Torah, it was written of him, “I am not a man of words.” Once he merited Torah, his tongue was healed and he began speaking words. From where? From what we have read in this passage: “These are the words that Moshe spoke.”',
    'This is the continuation of the Midrash beyond the portion already quoted in the existing footnote. It supplies the specific claim that Torah loosens the tongue and illustrates it through Moshe’s change from “not a man of words” to Devarim.')
add(89,'eruvin-all-conversation-is-torah',10,'Eruvin 54b:5',src('Eruvin 54b',5),
    'The school of Rav Anan taught: What is meant by “Riders on white donkeys, those who sit in judgment, and those who walk on the road—speak”? “Riders on donkeys” are Torah scholars who travel from city to city and from country to country to learn Torah. “White” means that they make it clear as midday. “Those who sit in judgment” are those who render a judgment true to its fullest truth. “Those who walk” are masters of Scripture. “On the road” are masters of Mishnah. “Speak” are masters of Talmud, all of whose conversation consists of words of Torah.',
    'The Gemara states explicitly that the masters of Talmud have Torah in all their conversation. This is a separate source from the leaf-and-fruit exposition already quoted at this point.')
ref='Dover Tzedek, Miscellany 1:8'
add(89,'dover-tzedek-ordinary-speech-and-absorbed-thought',10,ref,local('dover-tzedek',ref,16,20),
    'Our Sages said of Torah scholars that all their conversation is words of Torah. Since words of Torah are expressed in speech, all their speech becomes words of Torah. For wherever all a person’s thoughts are immersed, that immersion of thought is recognizable in every activity he undertakes, as is known. Similarly, the body’s eating and drinking, which resemble ordinary conversation, also become words of Torah and food and drink for the soul. Since through this the body is joined to the soul, and the body too derives benefit through a word of Torah, the body is then also included in holiness. Precisely through this comes holy inspiration; there is no room here to elaborate further.',
    'Rav Tzadok explains how an abiding immersion in Torah can shape ordinary speech and even bodily activity. The account includes the body’s participation in holiness and the resulting holy inspiration.',book='dover-tzedek')
add(89,'devarim-rabbah-scrolls-and-greek',11,'Devarim Rabbah 1:1',cut(src('Devarim Rabbah 1:1'),'אלה הדברים','לכך התירו שיכתבו בלשון יונית.'),
    '“These are the words.” A question of law: May a person of Israel write a Torah scroll in any language? The Sages taught: The difference between sacred books and tefillin and mezuzot is that the books may be written in any language. Rabban Gamliel says: Even for the books, they permitted writing only in Greek. What is Rabban Gamliel’s reason for allowing a Torah scroll to be written in Greek? Our teachers taught as follows. Bar Kappara said: It is written, “May God enlarge Yefet, and may he dwell in the tents of Shem”—the words of Shem are to be spoken in the languages of Yefet. Therefore they permitted writing in Greek.',
    'The opening of this Midrash records both the general permission for sacred books and Rabban Gamliel’s narrower position. Neither part is present in the existing quotation from the middle of the same Midrash.')
add(89,'yerushalmi-torah-conversation',12,'Jerusalem Talmud Berakhot 9:5:19',cut(src('Jerusalem Talmud Berakhot 9:5',19),'רבי יונה בשם רבי יוסי בן גזירה','ופיטטיא דאוריתא טבין.'),
    'Rabbi Yonah said in the name of Rabbi Yosi ben Gezirah: All chattering is bad, but chattering about Torah is good.',
    'This is the exact Yerushalmi formulation cited by Rav Tzadok. The following statement in the Yerushalmi concerns falsehood and is a separate teaching.')
add(89,'zohar-chadash-greece-and-surrounding-brightness',13,'Zohar Chadash, Yitro 339',extra('Zohar Chadash, Yitro',339),
    'Here is the mystery of the four kingdoms that surround everything. “A storm wind” is the kingdom of Babylon. “A great cloud” is the kingdom of Media. “A flashing fire” is the kingdom of Edom. “And brightness around it” is the kingdom of Greece: brightness surrounds them, but the brightness is not within them, for it is written “around.” For among all the kingdoms, none are as close to the path of faith as they are. Here too, among these shells, none is as close to the inner core as this one. Brightness surrounds it, but the brightness is not within it; rather, it comes out from the core and shines all around.',
    'The Zohar Chadash identifies Greece with surrounding brightness. The quotation preserves its central qualification: the brightness surrounds this kingdom and does not originate within it.')
add(89,'shulchan-arukh-greek-translation-and-darkness',15,'Shulchan Arukh, Orach Chayim 580:2',cut(extra('Shulchan Arukh, Orach Chayim 580:2'),'בשמונה בטבת','והיה חושך בעולם שלשה ימים'),
    'On the eighth of Tevet, the Torah was written in Greek in the days of King Ptolemy, and there was darkness in the world for three days.',
    'Shulchan Arukh records the tradition of darkness following the Greek translation, within its list of commemorative fast days. The date in this source is the eighth of Tevet.',anchorEnd='לִיוָנִית')
add(89,'soferim-ptolemy-and-the-transmitted-changes',15,'Tractate Soferim 1:8',extra('Tractate Soferim 1:7-8',2),
    'There was also an incident involving King Ptolemy, who gathered seventy-two elders and placed them in seventy-two houses, without revealing why he had gathered them. He entered each one’s house and said: “Write for me the Torah of Moshe your teacher.” The Omnipresent placed counsel in each one’s heart, and their minds agreed upon one understanding, so that each wrote a Torah separately for him. They changed thirteen things in it. These are they: “God created in the beginning”; “God said: I shall make a human being in an image and likeness”; “He completed on the sixth day and rested on the seventh”; “Male and female He created him”; “Come, I shall descend and confuse there”; “She laughed among her relatives, saying”; “For in their anger they killed a man, and in their willfulness they uprooted a feeding trough”; “Moshe took his wife and sons and mounted them upon bearers of people”; “The dwelling of the children of Israel, who dwelt in the land of Egypt and in the land of Canaan, was thirty years and four hundred years”; “Against the young men of the children of Israel He did not stretch out His hand”; “I have not taken one valuable thing from them”; “The short-legged one”; “Which Hashem your God allotted to give light to all the peoples under all the heavens”; “Which I did not command them to worship.”',
    'This source explicitly introduces “thirteen changes” and supplies the full transmitted list. The wording and list are preserved as transmitted, without deleting an item to reconcile the heading. The quoted phrases are the translation’s alterations, rather than quotations of the unaltered biblical wording.',anchorEnd='וְשִׁנּוּ י"ג דְּבָרִים')
ref='Peri Tzadik, Achrei Mot 5:1'
add(89,'peri-tzadik-permitted-disciplines-and-greek-wisdom',17,ref,cut(local('peri-tzadik',ref),'ובזלע"ז יש ז\' חכמות','רק סביב וכמ"ש בזה"ח.'),
    'Correspondingly, on the opposite side there are seven disciplines of wisdom. These, however, are permitted disciplines, and there is no prohibition in them; they are from the shell of nogah. As the Zohar Chadash says in Yitro, when enumerating the four shells: “Brightness around it” is the kingdom of Greece, which is surrounded by brightness, because among all the kingdoms none are as close to the path of faith as it is. This means that in Greek wisdom some attained an intellectual understanding of upright qualities. Yet “what wisdom have they,” since they are only from the shell of nogah: the brightness is not within them, but only around them, as stated in the Zohar Chadash.',
    'This parallel preserves Rav Tzadok’s explicit qualification that the seven disciplines themselves are permitted. He then discusses Greek moral understanding through the Zohar’s distinction between inward light and surrounding brightness.',book='peri-tzadik')
ref='Likkutei Maamarim, Compositions on the Festivals 11:13'
add(89,'likkutei-healing-speech-with-torahs-fire',8,ref,local('likkutei-maamarim',ref,8,13),
    'This is the healing of a tongue that chatters excessively: through the Torah’s Tree of Life, the whole body becomes fire, as stated at the end of Chagigah from the verse, “Are not My words like fire, declares Hashem?” Through speaking words of Torah with vitality, the combination of letters at the root of one’s life becomes like this, so that one is wholly fire. It is said that fire purifies, for impurity has no place in fire at all. This heals the past as well, like heating with fire to remove absorbed forbidden matter. All one’s conversation becomes Torah, since it comes from the burning fire—that is, the vitality burning within.',
    'Rav Tzadok explains how Torah can heal habitual speech and its earlier damage. The comparison is to purification by fire, and the passage concludes with the transformation of ordinary conversation.',book='likkutei-maamarim')

ref='Likkutei Maamarim, On Book of Joshua 5'
add(90,'likkutei-creation-as-the-book-of-divine-wisdom',0,ref,local('likkutei-maamarim',ref,18,30),
    'To explain this, know that a “book” is the inscription of words of wisdom. It makes no difference whether they are inscribed on paper, parchment, or something else, just as the Torah existed before the world was created; see Midrash Konen, section one. When wisdom is inscribed in the mind, the mind too is a book of wisdom. When a person composes a book, this means revealing his wisdom to all, with his wisdom stored within it. Similarly, we find the blessed God’s wisdom revealed in the world, for He created the world with wisdom, as it says, “With wisdom He founded the earth”; as stated in Rosh Hashanah, “He created everything with His wisdom”; and in Targum Yonatan, “In the beginning” is rendered “With wisdom.” Creation reveals His wisdom and is therefore like a book on which all His wisdom is inscribed. It is called the blessed God’s book, as we learn at the beginning of Sefer Yetzirah that He engraved His world through three books. This is the book mentioned in Avot: “All your deeds are written in the book”; see Reshit Chokhmah, Gate of Repentance, chapter five, in the name of Rabbi Yosef Yaavetz. Concerning this, see Avodah Zarah: “Did Adam the first man have a book? This teaches that He showed him…” Bava Metzia mentions Adam’s book, which included all the souls; this is what is called Adam’s book. See Avodat Yisrael on Nitzavim concerning being written for life in the book; Raavad’s commentary at the beginning of Sefer Yetzirah concerning the opening of three books; and Shaarei HaYichudim, gate three, the end of chapter thirty-eight, concerning Adam’s book and Chanoch’s book. The Torah too is the pattern of all creation, as it is compared at the beginning of Bereshit Rabbah; therefore it too is called the book of His wisdom.',
    'Rav Tzadok explains the image of Torah as the pattern of creation through the broader meaning of a book: the inscription and disclosure of wisdom. The selected unit also connects this image with the book containing the souls.',book='likkutei-maamarim')
add(90,'zohar-torah-israel-and-god-interconnected',2,'Zohar III 73a',
    'דתנינן ג\' דרגין אינון מתקשרן דא בדא - קב"ה אורייתא וישראל. וכל חד - דרגא על דרגא - סתים וגליא. קב"ה - דרגא על דרגא, סתים וגליא. אורייתא הכי נמי - סתים וגליא. ישראל הכי נמי - דרגא על דרגא! הדא הוא דכתיב "מגיד דבריו ליעקב חקיו ומשפטיו לישראל". תרין דרגין אינון - יעקב וישראל - חד גליא וחד סתים.',
    'For we have learned: Three levels are interconnected with one another—the Holy One, blessed be He, Torah, and Israel. Each, level upon level, is concealed and revealed. The Holy One, blessed be He: level upon level, concealed and revealed. Torah likewise: concealed and revealed. Israel likewise: level upon level. This is as it is written: “He tells His words to Yaakov, His statutes and judgments to Israel.” There are two levels—Yaakov and Israel—one revealed and one concealed.',
    'The Zohar’s wording is that the three are interconnected, and it distinguishes concealed and revealed levels within each. This supplies the original passage underlying the expression used here.',url='https://he.wikisource.org/wiki/זהר_חלק_ג_עג_א',anchorEnd='שֶׁהֵם וְאוֹרַיְיתָא חַד כַּנּוֹדָע')
E[-1]['sourceEvidence'][0].update(webRef='turn75view0',sourceLocation='Unit beginning דתנינן ג דרגין through חד גליא וחד סתים; hidden and revealed qualifications retained.')
add(90,'shelah-six-hundred-thousand-soul-roots',2,'Shenei Luchot HaBerit, Torah Shebikhtav, Korach, Torah Ohr 2',cut(src('Shenei Luchot HaBerit, Torah Shebikhtav, Korach, Torah Ohr',2),'ודע כי','ענפים מהם.'),
    'Know that the number of the children of Israel was six hundred thousand. The kabbalists said that these are six hundred thousand souls issuing from the six hundred thousand letters of the Torah, for the Torah’s spiritual reality is the souls of Israel. The generation that received the Torah comprised these six hundred thousand souls; the generations that came after them are all branches issuing from them.',
    'Shelah states the correspondence between the founding generation, the letters of Torah, and the later generations as branches. He proceeds to ask how Levi is included and develops the distinction between general roots and their particulars; the selected quotation states the initial correspondence.')
ref="Peri Tzadik, Ha'Azinu 5:1"
add(90,'peri-tzadik-letters-sparks-and-each-souls-portion',2,ref,cut(local('peri-tzadik',ref),'וכל נפש יש לו נר מיוחד',"והוא נר שלו נר ה' נשמת אדם."),
    'Every soul has its own particular lamp, the human soul. Torah too is a lamp: “Torah is light,” and “light means Torah,” as stated in Megillah. This is “Your word is a lamp to my feet and a light to my path.” Each person of Israel has a portion in Torah that is his own lamp. In the generation of the wilderness, the fundamental number was six hundred thousand souls, corresponding to the six hundred thousand letters of Torah, as is said: Yisrael forms the initials of “There are six hundred thousand letters in the Torah.” Although the numerical count does not match, each letter divides into sparks; this is the Written Torah. Subsequently, through the Torah insights in which the blessed God brings forth a new teaching every day, as stated in Bereshit Rabbah, the souls of Israel increase. This is what we ask: “Give us our portion in Your Torah,” for every person of Israel has a portion in Torah, which is his lamp—“The soul of man is Hashem’s lamp.”',
    'This parallel includes Rav Tzadok’s express qualification that the ordinary count of letters does not equal the stated number: the correspondence is through the letters’ division into sparks. It then connects new Torah teachings with the multiplication of souls.',book='peri-tzadik')
ref='Likkutei Maamarim, Compositions on the Festivals 16:37'
add(90,'likkutei-new-torah-and-new-worldly-wisdom',8,ref,local('likkutei-maamarim',ref,18,26),
    'When a person of Israel develops something new in the wisdom of Torah, which is the blessed God’s wisdom, this wisdom spreads through all the worlds. In the physical world too, some matter of wisdom concerning this world is renewed correspondingly, drawn forth through this wisdom newly revealed in Hashem’s Torah and His service. The wise people of the nations of the world in that generation can receive it and develop it, and an observer will think that they originated it.',
    'Rav Tzadok describes a spiritual relationship between new Torah insight and developments in worldly knowledge. This gives his fuller account of the connection asserted in the present ois.',book='likkutei-maamarim')
ref='Poked Akarim 4:2'
add(90,'poked-new-oral-torah-and-world-governance',8,ref,local('poked-akarim',ref,35,41),
    'All the Oral Torah is hinted at in the Written Torah. Therefore whatever has already been revealed from the Oral Torah and is written down in the books of Israel’s sages has, for us, the character of Written Torah: these hints in the Written Torah have already been revealed and have become a fixed order of governance. The world’s entire governance according to Torah follows the Written Torah and its oral interpretation. Whatever is already revealed from the Oral Torah means that the governance too is already revealed in that form, just as the law is fixed and known to all. Every renewal in governance comes through the renewal of Oral Torah revealed to the hearts of Israel’s sages in that generation. According to those new insights are the renewals in governance, through the righteous person who rules in the fear of God—the true Torah scholar among Israel’s sages.',
    'This passage distinguishes an established body of revealed teaching from new Oral Torah insight and explains how that distinction corresponds to established and renewed governance of the world.',book='poked-akarim')
ref='Takanat HaShavin 6:89'
add(90,'takanat-generations-rooted-in-written-and-oral-torah',6,ref,local('takanat-hashavin',ref,4,10),
    'All the souls of the children of Israel have their root in Torah, for “Torah and Israel are one.” In the mystery of the souls of the wilderness generation—the generation of Moshe who received the Written Torah—their root is in the letters of the Written Torah, as is known. As for the other generations, which are branches spreading from that generation, it appears to me that their root is in the Oral Torah, the unfolding of the Written Torah. Nothing is absent from the hints of the Written Torah, but it is there in allusion and concealment. Similarly, the souls of all the other generations were stored and included in concealment in the wilderness generation, since they issued from them. According to the Oral Torah renewed in each generation, so are the souls of the children of Israel in that generation.',
    'Rav Tzadok offers the distinction between the soul-roots of the first generation and later generations as his own explanation—“it appears to me.” The quotation preserves that qualification and the inclusion of later generations within the original root.',book='takanat-hashavin')

